import * as T from 'three';
import {SPACES,CATEGORIES,WORKS,spaceFromHash,filterWorks} from './catalog.js';
import {createWorld,disposeWorld,VIEWPOINTS} from './worlds.js';
import {SpatialNavigation} from './navigation.js';
import {RoomEnvironment} from './vendor/RoomEnvironment.js';

const $=s=>document.querySelector(s),canvas=$('#world');
const reducedQuery=matchMedia('(prefers-reduced-motion: reduce)');
let renderer,world,nav,current=spaceFromHash(location.hash),transitioning=false,elapsed=0,paused=reducedQuery.matches,last=performance.now(),raf,quality='balanced',toastTimer,transitionTimer,category='all',tween;
const camera=new T.PerspectiveCamera(45,innerWidth/innerHeight,.1,3000);
let environmentTarget;
function prepareEnvironment(){const generator=new T.PMREMGenerator(renderer),room=new RoomEnvironment();environmentTarget=generator.fromScene(room,.04);room.dispose();generator.dispose();}
function applyEnvironment(scene){scene.environment=environmentTarget?.texture;scene.environmentIntensity=.7;}
const raycaster=new T.Raycaster();
const labels=new Map();
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function interacted(){tween=null;$('.scene-heading').classList.add('compact');$('.space-nav').classList.add('exploring');}
function restoreHeading(){$('.scene-heading').classList.remove('compact');$('.space-nav').classList.remove('exploring');}
function reset(){if(!nav)return;tween=null;nav.reset();restoreHeading();$('#viewpoints').querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===0)));toast('已回到当前空间的初始视角');}
function updateHeading(){const {id,name,en,number,description,color}=current;document.body.dataset.space=id;document.documentElement.style.setProperty('--accent',color);$('#scene-eyebrow').textContent=`${number} / ${en}`;$('#scene-title').innerHTML=id==='hub'?'PLAY<span class="title-outline">GROUND</span><span class="title-star">✳</span>':id==='digital'?'DIGITAL<span class="title-outline">INFINITY</span>':id==='ocean'?'PELAGIC<span class="title-outline">WORLD</span>':'SHIFTING<span class="title-outline">CASTLE</span>';$('#scene-chinese').textContent=id==='hub'?'想象，无须边界。':name;$('#scene-description').textContent=description;$('#explore').hidden=id!=='hub';$('#return').hidden=id==='hub';document.title=`${name} — Sovue Playground`;document.querySelectorAll('.space-link').forEach(b=>{b.classList.toggle('active',b.dataset.space===id);if(b.dataset.space===id)b.setAttribute('aria-current','location');else b.removeAttribute('aria-current');});restoreHeading();}
function rebuildLabels(){$('#portal-labels').replaceChildren();labels.clear();for(const p of world.portals){const space=SPACES.find(s=>s.id===p.id);const el=document.createElement('button');el.className='portal-label';el.innerHTML=`<i></i>${space.number} / ${space.en} ↗`;el.setAttribute('aria-label',`进入${space.name}`);el.addEventListener('click',()=>navigate(p.id));$('#portal-labels').append(el);labels.set(p.id,el);}}
function goToView(pose){if(!nav||transitioning)return;interacted();const up=new T.Vector3(...(pose.up||[0,1,0]));if(reducedQuery.matches){camera.position.fromArray(pose.position);nav.target.fromArray(pose.target);camera.up.copy(up);camera.lookAt(nav.target);}else{tween={start:performance.now(),from:camera.position.clone(),to:new T.Vector3(...pose.position),targetFrom:nav.target.clone(),targetTo:new T.Vector3(...pose.target),upFrom:camera.up.clone(),upRotation:new T.Quaternion().setFromUnitVectors(camera.up.clone(),up)};}}
function rebuildViews(){$('#viewpoints').replaceChildren();VIEWPOINTS[current.id].forEach((pose,i)=>{const button=document.createElement('button');button.textContent=`0${i+1} / ${pose.name}`;button.setAttribute('aria-pressed',String(i===0));button.addEventListener('click',()=>{goToView(pose);$('#viewpoints').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));});$('#viewpoints').append(button);});if(world.reconfigure){const button=document.createElement('button');button.textContent='↻ 空间重排';button.addEventListener('click',()=>{world.reconfigure(paused||reducedQuery.matches);toast('整座无限城正在分块转动、重排');});$('#viewpoints').append(button);}}
function previewPortals(){if(!renderer)return;for(const portal of world.portals){const preview=createWorld(portal.id),previewCamera=new T.PerspectiveCamera(54,3.5/5.5,.1,3000),target=new T.WebGLRenderTarget(224,352);applyEnvironment(preview.scene);previewCamera.position.fromArray(preview.pose.position).multiplyScalar(1.15);previewCamera.lookAt(new T.Vector3(...preview.pose.target));preview.animate(0,previewCamera,0);renderer.setRenderTarget(target);renderer.render(preview.scene,previewCamera);renderer.setRenderTarget(null);portal.object.material.map=target.texture;portal.object.material.color.set('#ffffff');portal.object.material.opacity=.9;portal.object.material.needsUpdate=true;portal.object.userData.previewTarget=target;disposeWorld(preview);}}
function switchWorld(id){const next=SPACES.find(s=>s.id===id)||SPACES[0];if(world)disposeWorld(world);world=createWorld(next.id);applyEnvironment(world.scene);previewPortals();current=next;nav?.setPose(world.pose);$('#world-caption').innerHTML=world.caption;updateHeading();rebuildLabels();rebuildViews();canvas.dataset.space=current.id;canvas.dataset.model=JSON.stringify(world.scene.userData);}
function navigate(id){if(transitioning||!SPACES.some(s=>s.id===id))return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(id===current.id){reset();return;}if(!renderer){current=SPACES.find(s=>s.id===id);updateHeading();return;}transitioning=true;nav.enabled=false;nav.keys.clear();tween=null;const next=SPACES.find(s=>s.id===id);$('#transition-number').textContent=next.number;$('#transition-name').textContent=next.name;
  const entrance=world.portals.find(p=>p.id===id),approach=entrance&&!reducedQuery.matches?550:0;
  if(approach){interacted();tween={start:performance.now(),duration:550,from:camera.position.clone(),to:entrance.object.position.clone().add(new T.Vector3(0,0,7)),targetFrom:nav.target.clone(),targetTo:entrance.object.position.clone(),upFrom:camera.up.clone(),upRotation:new T.Quaternion().setFromUnitVectors(camera.up.clone(),new T.Vector3(0,1,0))};}
  setTimeout(()=>$('#transition').classList.add('visible'),approach);
  clearTimeout(transitionTimer);transitionTimer=setTimeout(()=>{try{tween=null;switchWorld(id);if(location.hash!==`#${id}`)location.hash=id;setTimeout(()=>{$('#transition').classList.remove('visible');nav.enabled=true;transitioning=false;},reducedQuery.matches?0:180);}catch(error){console.error(error);$('#transition').classList.remove('visible');transitioning=false;nav.enabled=true;toast('空间载入失败，请返回主馆后重试');}},approach+(reducedQuery.matches?0:450));
}
function dialogOpen(id){const d=$(id);d.showModal();if(nav){nav.enabled=false;nav.keys.clear();}tween=null;}
for(const space of SPACES.slice(1)){const button=document.createElement('button');button.className='space-link';button.dataset.space=space.id;button.innerHTML=`<span class="num">${space.number}</span><span><strong>${space.name}</strong><small>${space.en}</small></span><span class="arrow">↗</span>`;button.addEventListener('click',()=>navigate(space.id));$('#space-links').append(button);}
for(const space of SPACES){const button=document.createElement('button');button.className='map-item';button.innerHTML=`<b>${space.number}</b><span><strong>${space.name}</strong><small>${space.en}</small></span><span>↗</span>`;button.addEventListener('click',()=>navigate(space.id));$('#map-spaces').append(button);}
$('#map-open').addEventListener('click',()=>dialogOpen('#map-dialog'));$('#collection-open').addEventListener('click',()=>dialogOpen('#collection-dialog'));$('#help-open').addEventListener('click',()=>dialogOpen('#help-dialog'));
for(const dialog of document.querySelectorAll('dialog')){dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{if(nav)nav.enabled=!transitioning;});}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('dialog[open]');if(open){e.preventDefault();open.close();}}},true);
function renderWorks(){const found=filterWorks(WORKS,category,$('#search').value);$('#works').replaceChildren();if(!found.length){const empty=document.createElement('div');empty.className='empty-state';empty.innerHTML=`<div class="empty-symbol">⌑</div><h3>${$('#search').value?'没有找到这件作品':'故事，正在发生。'}</h3><p>${$('#search').value?'试试其他关键词，或切换作品分类。':'展馆已经开放，作品将陆续抵达。<br>先去空间里走走，下一次也许就会遇见新的发现。'}</p>`;$('#works').append(empty);return;}for(const work of found){const link=document.createElement('a');link.className='work-card';let url;try{url=new URL(work.url,location.href);if(!['http:','https:'].includes(url.protocol))continue;}catch{continue;}link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';link.innerHTML=`${escapeHTML(work.title)} ↗<small>${escapeHTML(work.description||'')}</small>`;$('#works').append(link);}}
for(const cat of CATEGORIES){const button=document.createElement('button');button.textContent=cat.name;button.setAttribute('aria-pressed',String(cat.id==='all'));button.addEventListener('click',()=>{category=cat.id;$('#categories').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderWorks();});$('#categories').append(button);}$('#search').addEventListener('input',renderWorks);renderWorks();$('.count').textContent=String(WORKS.length).padStart(2,'0');
$('#return').addEventListener('click',()=>navigate('hub'));$('#reset').addEventListener('click',reset);$('.brand').addEventListener('click',e=>{e.preventDefault();navigate('hub');});
$('#roll-left').addEventListener('click',()=>{if(nav){interacted();nav.roll(Math.PI/6);}});$('#roll-right').addEventListener('click',()=>{if(nav){interacted();nav.roll(-Math.PI/6);}});
$('#explore').addEventListener('click',()=>{if(!nav)return;interacted();if(reducedQuery.matches){nav.camera.position.set(29,16,30);nav.target.set(0,5,-6);nav.camera.lookAt(nav.target);}else tween={start:performance.now(),from:camera.position.clone(),to:new T.Vector3(29,16,30),targetFrom:nav.target.clone(),targetTo:new T.Vector3(0,5,-6)};toast('拖动环顾 · 点击发光入口进入空间 · ⌖ 恢复视角');});
function updateMotion(){$('#motion').textContent=paused?'▷':'Ⅱ';$('#motion').setAttribute('aria-pressed',String(paused));$('#motion').setAttribute('aria-label',paused?'播放环境动效':'暂停环境动效');canvas.dataset.motion=paused?'paused':'playing';}
$('#motion').addEventListener('click',()=>{paused=!paused;updateMotion();toast(paused?'环境动效已暂停，仍可自由探索':'环境动效已开启');});reducedQuery.addEventListener('change',e=>{paused=e.matches;updateMotion();});updateMotion();
function resize(){if(!renderer)return;const w=canvas.clientWidth,h=canvas.clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h,false);renderer.setPixelRatio(Math.min(devicePixelRatio,quality==='high'?2:quality==='balanced'?1.25:.75));}
$('#quality').addEventListener('click',()=>{const values=['balanced','high','reduced'];quality=values[(values.indexOf(quality)+1)%3];$('#quality').textContent={balanced:'BAL',high:'HI',reduced:'LOW'}[quality];$('#quality').setAttribute('aria-label',`画质：${{balanced:'均衡',high:'高',reduced:'节能'}[quality]}`);resize();toast(`已切换${{balanced:'均衡',high:'高',reduced:'节能'}[quality]}画质`);});
$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#experience').requestFullscreen();}catch{toast('当前浏览器不支持全屏，可使用浏览器全屏快捷键');}});window.addEventListener('resize',resize);
for(const b of document.querySelectorAll('[data-move]'))b.addEventListener('click',()=>{if(nav){interacted();nav.dolly(b.dataset.move==='forward'?-.18:.18);}});
window.addEventListener('hashchange',()=>{const space=spaceFromHash(location.hash);if(space.id!==current.id)navigate(space.id);});
canvas.addEventListener('click',e=>{if(!renderer||!nav||nav.moved||transitioning)return;const rect=canvas.getBoundingClientRect();raycaster.setFromCamera(new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hits=raycaster.intersectObjects(world.portals.map(p=>p.object));if(hits.length)navigate(hits[0].object.userData.portal);});
function updateLabels(){for(const p of world.portals){const el=labels.get(p.id),v=p.position.clone().project(camera),visible=v.z<1&&v.z>-1&&Math.abs(v.x)<.9&&Math.abs(v.y)<.75;el.hidden=!visible;if(visible)el.style.transform=`translate(${(v.x*.5+.5)*canvas.clientWidth}px,${(-v.y*.5+.5)*canvas.clientHeight+22}px) translate(-50%,0)`;}}
const debug=new URLSearchParams(location.search).has('debug');let debugEl,frameCount=0,sampleStart=performance.now();if(debug){debugEl=document.createElement('div');debugEl.id='debug';$('#experience').append(debugEl);}
function tick(now){raf=requestAnimationFrame(tick);const dt=Math.min((now-last)/1000,.05);last=now;if(!paused&&!document.querySelector('dialog[open]'))elapsed+=dt;nav.update(dt);if(tween){const progress=Math.min((now-tween.start)/(tween.duration||1400),1),ease=1-Math.pow(1-progress,3);camera.position.lerpVectors(tween.from,tween.to,ease);nav.target.lerpVectors(tween.targetFrom,tween.targetTo,ease);if(tween.upRotation)camera.up.copy(tween.upFrom).applyQuaternion(new T.Quaternion().slerp(tween.upRotation,ease));camera.lookAt(nav.target);if(progress===1)tween=null;}world.animate(elapsed,camera,dt);renderer.render(world.scene,camera);updateLabels();frameCount++;if(frameCount%12===0){const p=camera.position;$('#coordinates').textContent=`X ${p.x>=0?'+':''}${p.x.toFixed(0).padStart(3,'0')} · Y ${p.y>=0?'+':''}${p.y.toFixed(0).padStart(3,'0')} · Z ${p.z>=0?'+':''}${p.z.toFixed(0).padStart(3,'0')}`;canvas.dataset.camera=JSON.stringify({position:p.toArray(),up:camera.up.toArray(),target:nav.target.toArray()});}if(debug&&now-sampleStart>1000){debugEl.textContent=`${Math.round(frameCount*1000/(now-sampleStart))} FPS / ${((now-sampleStart)/frameCount).toFixed(1)} MS · ${renderer.info.render.calls} CALLS · ${renderer.info.render.triangles} TRIS`;sampleStart=now;frameCount=0;}}
document.addEventListener('visibilitychange',()=>{if(!renderer)return;if(document.hidden){cancelAnimationFrame(raf);nav.keys.clear();}else{last=performance.now();raf=requestAnimationFrame(tick);}});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();cancelAnimationFrame(raf);$('#fallback').hidden=false;});canvas.addEventListener('webglcontextrestored',()=>location.reload());
try{renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;prepareEnvironment();nav=new SpatialNavigation(camera,canvas,interacted);switchWorld(current.id);resize();renderer.render(world.scene,camera);$('#loading').classList.add('done');last=performance.now();sampleStart=last;frameCount=0;raf=requestAnimationFrame(tick);canvas.dataset.ready='true';}catch(error){console.error(error);$('#loading').classList.add('done');$('#fallback').hidden=false;updateHeading();}
